#!/usr/bin/env bash
# Print the three most frequent client addresses.  Equal counts retain the
# order in which the addresses first occurred in the log.
set -euo pipefail

script_dir=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)
log="$script_dir/access.log"

if [[ ! -r "$log" ]]; then
    printf 'top_talkers.sh: cannot read %s\n' "$log" >&2
    exit 1
fi

awk '
{
    ip = $1
    if (!(ip in count))
        first[ip] = ++sequence
    ++count[ip]
}
END {
    # Select rather than sort so the explicit first-seen tie-breaker is
    # independent of awk hash iteration order.
    for (rank = 1; rank <= 3; ++rank) {
        best = ""
        for (ip in count) {
            if (best == "" || count[ip] > count[best] ||
                (count[ip] == count[best] && first[ip] < first[best]))
                best = ip
        }
        if (best == "")
            break
        print best
        delete count[best]
    }
}
' "$log"
